async function meshKick(d: MeshDevice) {
  if (meshBusy.value) return;
  if (
    !confirm(
      `把「${d.name}」移出?\n\n它将无法再连入你的任何设备,已挂的盘会立刻收回。\n重新用邮箱登录可以恢复。`
    )
  )
    return;
  meshBusy.value = true;
  try {
    const result = await invoke<{
      ok: boolean;
      partial: boolean;
      cloudRevoked: boolean;
      localRevoked: boolean;
      retryable: boolean;
      cloudError?: string;
      localError?: string;
    }>("mesh_device_remove", { nodeId: d.nodeId });
    if (result.ok) {
      toast.info("已从云端设备网和本机准入中移出");
    } else {
      const missing = [
        !result.localRevoked ? `本机撤销失败:${result.localError || "未知错误"}` : "",
        !result.cloudRevoked ? `云端撤销失败:${result.cloudError || "未知错误"}` : "",
      ].filter(Boolean);
      toast.error(`已完成能完成的撤销；${missing.join("；")}。恢复网络后可直接重试。`);
    }
    await loadMesh();
  } catch (e) {
    toast.error(errMsg(e));
  } finally {
    meshBusy.value = false;
  }
}

/** 「3 分钟前」这类人话时间。台账上「上次上线」用它。 */
function agoText(ts: number): string {
