        params![uid, actor.device_id], |r| r.get(0),
    ).map_err(|e| e.to_string())?;
    let needs_approval = !first && devices.len() > 1
        && db::now() < actor.enrolled_at + (config.new_device_window_hours * 3600) as i64;
    if needs_approval {
