    // 设备网偶尔连不上时(云端联系不上、iroh 还没就绪),粘码是有用的兜底,不能堵死。
    if (
      conn.uid &&
      conn.uid === account.uid &&
      !confirm(
        `「${conn.hostName ?? "这台设备"}」是你自己账号(${conn.email || account.label})的机器。\n\n` +
