fn login_cooldown_check(username: &str) -> Result<(), String> {
    let g = LOGIN_GATE.lock().unwrap();
    if let Some((fails, until)) = g.get(username) {
        if *fails >= LOGIN_FAIL_THRESHOLD {
            let left = *until - now();
